import java.util.*;
public class LinkedQueue { static class Node{int x;Node next;Node(int x){this.x=x;}} Node front,back; public void add(int x){Node n=new Node(x);if(back==null)front=back=n;else{back.next=n;back=n;}} public int remove(){if(front==null)throw new NoSuchElementException("empty queue");int x=front.x;front=front.next;if(front==null)back=null;return x;} public static void run(){LinkedQueue q=new LinkedQueue();q.add(5);q.add(6);q.add(7);System.out.println("Queue removes in FIFO order: "+q.remove()+", "+q.remove());System.out.println("Invariant: front is oldest element; add/remove O(1).\n");} public static void main(String[] args){run();}}
